// Portable, self-contained prototype snapshot. Pure data: no browser storage or DB writes.
// Identity and adjacency are regenerated by the fixed grid algorithm on restore.
import {createGlobalGrid,assertGlobalGrid,GLOBAL_GRID_CELLS,GLOBAL_GRID_FREQUENCY,GRID_FORMAT_VERSION} from './global-config.mjs';
import {openGlobalTerrain} from './terrain-edits.mjs';
import {heightFieldChecksum as checksumHeights,quantizeHeight,isTerrainHeight} from '../../src/features/worldMap/core/terrainField.mjs';
export function exportGlobalTerrainSnapshot(state){
 assertGlobalGrid(state.grid);
 const heights=Array.from(state.grid.heights,quantizeHeight);
 return {
  format:'nexus-spherical-grid-prototype',version:GRID_FORMAT_VERSION,
  frequency:GLOBAL_GRID_FREQUENCY,cells:GLOBAL_GRID_CELLS,
  heightScaleMetres:100,seaLevel:0,
  oceanSeed:state.oceanSeed,revision:state.revision,
  heights,checksum:checksumHeights(heights)
 };
}
export function importGlobalTerrainSnapshot(snapshot){
 if(!snapshot||typeof snapshot!=='object'||Array.isArray(snapshot)||
   snapshot.format!=='nexus-spherical-grid-prototype'||
   snapshot.version!==GRID_FORMAT_VERSION||
   snapshot.frequency!==GLOBAL_GRID_FREQUENCY||
   snapshot.cells!==GLOBAL_GRID_CELLS||
   snapshot.heightScaleMetres!==100||snapshot.seaLevel!==0)
  throw new Error('Unsupported spherical Grid snapshot contract');
 if(!Array.isArray(snapshot.heights)||snapshot.heights.length!==GLOBAL_GRID_CELLS)
  throw RangeError('Wrong spherical Grid height array length');
 if(!snapshot.heights.every(isTerrainHeight))
  throw RangeError('Invalid finite height');
 if(snapshot.checksum!==checksumHeights(snapshot.heights))
  throw Error('Spherical Grid height checksum mismatch');
 if(!Number.isInteger(snapshot.oceanSeed)||snapshot.oceanSeed<0||snapshot.oceanSeed>=GLOBAL_GRID_CELLS||
    snapshot.heights[snapshot.oceanSeed]>=0)
  throw RangeError('Invalid ocean seed');
 if(!Number.isSafeInteger(snapshot.revision)||snapshot.revision<0)
  throw RangeError('Invalid revision');
 const grid=createGlobalGrid();
 grid.heights.set(snapshot.heights);
 const state=openGlobalTerrain(grid,snapshot.oceanSeed);
 state.revision=snapshot.revision;
 return state;
}
